{
    public EntityCommandBuffer.ParallelWriter Ecb;
    void Execute(Entity entity, [ChunkIndexInQuery] int sortKey, in Hit hit)
    {
        Ecb.AddComponent<Stunned>(sortKey, entity);   // recorded, not applied
        Ecb.RemoveComponent<Hit>(sortKey, entity);
    }
}

// in OnUpdate:
var ecb = SystemAPI.GetSingleton<EndSimulationEntityCommandBufferSystem.Singleton>()
    .CreateCommandBuffer(state.WorldUnmanaged);
new StunOnHitJob { Ecb = ecb.AsParallelWriter() }.ScheduleParallel();
// no Playback(), no Dispose(): the ECB system does both

var ecb = new EntityCommandBuffer(Allocator.TempJob);
JobHandle h = new StunOnHitJob { Ecb = ecb.AsParallelWriter() }
    .ScheduleParallel(state.Dependency);
h.Complete();                        // recording must be finished
ecb.Playback(state.EntityManager);   // main thread; the changes happen here
ecb.Dispose();                       // you created it, you dispose it

