using Unity.Burst;
using Unity.Entities;

public struct Health : IComponentData { public float Value; }

[BurstCompile]
public partial struct DestroyDeadJob : IJobEntity
{
    public EntityCommandBuffer.ParallelWriter Ecb;
    void Execute(Entity entity, [ChunkIndexInQuery] int sortKey, in Health health)
    {
        if (health.Value <= 0f) Ecb.DestroyEntity(sortKey, entity); // recorded only
    }
}

[BurstCompile]
public partial struct DeathSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var ecb = SystemAPI.GetSingleton<EndSimulationEntityCommandBufferSystem.Singleton>()
            .CreateCommandBuffer(state.WorldUnmanaged);
        new DestroyDeadJob { Ecb = ecb.AsParallelWriter() }.ScheduleParallel();
        // the ECB system waits for the job, plays the commands back
        // at the end of the simulation group and disposes the buffer
    }
}

