public struct Stunned : IComponentData, IEnableableComponent
{
    public float TimeLeft;
}

// the archetype stays the same: only the entity's enabled bit flips
state.EntityManager.SetComponentEnabled<Stunned>(e, true);
bool stunned = state.EntityManager.IsComponentEnabled<Stunned>(e);

// queries treat a disabled component as missing:
// this job only visits entities whose Stunned is enabled
partial struct StunTimerJob : IJobEntity
{
    public float DeltaTime;
    void Execute(ref Stunned stunned) => stunned.TimeLeft -= DeltaTime;
}
